from pathlib import Path
import re

ROOT = Path('cloudflare/runner3-core')
SIMPLE = ROOT / 'artifact-library-simple-entry.js'
V2 = ROOT / 'artifact-library-reader-v2-entry.js'

simple = SIMPLE.read_text(encoding='utf-8')
v2 = V2.read_text(encoding='utf-8')


def replace_once(source: str, old: str, new: str, label: str) -> str:
    count = source.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, got {count}')
    return source.replace(old, new, 1)

# Bump client identity so long-lived Reader tabs reload and pick up the UI fix.
simple = replace_once(simple, "reader_client_version:'v65'", "reader_client_version:'v65.1'", 'v65.1 server client version')
simple = replace_once(simple, "'x-r3-reader-client-version':'v65'", "'x-r3-reader-client-version':'v65.1'", 'v65.1 server version header')
v2 = replace_once(v2, "const R3_READER_CLIENT_VERSION_V63='v65';", "const R3_READER_CLIENT_VERSION_V63='v65.1';", 'v65.1 reader client version')

