main_pattern=re.compile(r"  async function r3ManageBookV65\(bookKey,title\)\{.*?\n(?=  function r3InstallMainManageV65\(\))",re.S)
simple,count=main_pattern.subn(main_runtime,simple,count=1)
if count!=1: raise SystemExit(f'v65.1 main manage replacement: expected 1 match, got {count}')
# Make the ellipsis control visually lighter; the bottom sheet now carries the hierarchy.
simple=simple.replace(".r3-manage-v65{appearance:none;border:0;border-left:1px solid #202832;background:#111820;color:#aeb9c6;width:42px;display:grid;place-items:center;padding:0;font:inherit;font-size:20px;font-weight:900;cursor:pointer}",".r3-manage-v65{appearance:none;border:0;background:transparent;color:#93a0ad;width:42px;display:grid;place-items:center;padding:0;font:inherit;font-size:20px;font-weight:900;cursor:pointer}.r3-manage-v65:active{background:#182028}",1)
simple=simple.replace("button.setAttribute('aria-label','Rename hoặc Delete')","button.setAttribute('aria-label','Tùy chọn sách')",1)

